// ShipmentPackage Package Information container.  For Return Shipments up to 20 packages are allowed. US/PR origin return movements are limited to only one package. For Mail Innovations and Simple Rate shipments only one package is allowed.
type ShipmentPackage struct {
	// AdditionalHandlingIndicator Additional Handling Required. The presence indicates additional handling is required, the absence indicates no additional handling is required. Additional Handling indicator indicates it's a non-corrugated package.
	AdditionalHandlingIndicator *string `json:"AdditionalHandlingIndicator,omitempty"`

	// Commodity Container to hold the Commodity information.  It is required if the Ground Freight Pricing Shipment indicator is present in the request.
	Commodity *PackageCommodity `json:"Commodity,omitempty"`

	// Description Merchandise description of package.  Required for shipment with return service.
	Description *string `json:"Description,omitempty"`

	// DimWeight Dimensional weight of shipment. Please visit ups.com for rules on calculating. There is one implied decimal place (e.g. 115 = 11.5).  If dimensions are provided, dimensional weight is ignored. For US/PR/CA shipments, dimensional weight is ignored
	DimWeight *PackageDimWeight `json:"DimWeight,omitempty"`

	// Dimensions Dimensions information container. Note: Currently dimensions are not applicable to Ground Freight Pricing.  Length + 2*(Width + Height) must be less than or equal to 165 IN or 330 CM. Required for Heavy Goods service. Package Dimension will be ignored for Simple Rate
	Dimensions *PackageDimensions `json:"Dimensions,omitempty"`

	// HazMatPackageInformation Required when number of hazmat containers in a package is greater than 1. It indicates whether all the hazmat materials are kept in a single box or multiple boxes.  Required when number of hazmat container in a package is greater than 1.
	HazMatPackageInformation *PackageHazMatPackageInformation `json:"HazMatPackageInformation,omitempty"`

	// LargePackageIndicator Presence of the indicator mentions that the package is Large Package.
	//
	// This is an empty tag, any value inside is ignored.
	LargePackageIndicator *string `json:"LargePackageIndicator,omitempty"`

	// MinimumBillableWeightIndicator Presence/Absence Indicator. Any value is ignored. If present, indicates that the package is qualified for minimum billable weight.   Applicable for UPS Worldwide Economy DDU service.
	MinimumBillableWeightIndicator *string `json:"MinimumBillableWeightIndicator,omitempty"`

	// NumOfPieces Number of Pieces. Applicable for Air Freight only
	NumOfPieces *string `json:"NumOfPieces,omitempty"`

	// OversizeIndicator Presence/Absence Indicator. Any value is ignored. If present, indicates that the package is over size.   Applicable for UPS Worldwide Economy DDU service.
	OversizeIndicator *string `json:"OversizeIndicator,omitempty"`

	// PackageServiceOptions Package Service Options container.
	PackageServiceOptions *PackagePackageServiceOptions `json:"PackageServiceOptions,omitempty"`

	// PackageWeight Container to hold package weight information.  Package weight is a required for Ground Freight Pricing shipments and Heavy Goods service. Package Weight will be ignored for Simple Rate.
	PackageWeight *PackagePackageWeight `json:"PackageWeight,omitempty"`

	// Packaging Packaging container.  Container for Packaging Type.
	Packaging PackagePackaging `json:"Packaging"`

	// PalletDescription Description of articles & special marks. Applicable for Air Freight only
	PalletDescription *string                   `json:"PalletDescription,omitempty"`
	ReferenceNumber   *[]PackageReferenceNumber `json:"ReferenceNumber,omitempty"`

	// SimpleRate SimpleRate Container
	SimpleRate *PackageSimpleRate `json:"SimpleRate,omitempty"`

	// UPSPremier UPS Premier Container.
	UPSPremier *PackageUPSPremier `json:"UPSPremier,omitempty"`

	// UnitPrice Unit price of the commodity. Applicable for Air Freight only  Limit to 2 digit after the decimal. The maximum length of the field is 12 including '.' and can hold up to 2 decimal place. (e.g. 999999999.99)
	UnitPrice *string `json:"UnitPrice,omitempty"`
}

// ShipmentPaymentInformation Payment information container for detailed shipment charges. The two shipment charges that are available for specification are Transportation charges and Duties and Taxes.  It is required for non-Ground Freight Pricing shipments only.
type ShipmentPaymentInformation struct {
	ShipmentCharge []PaymentInformationShipmentCharge `json:"ShipmentCharge"`

	// SplitDutyVATIndicator Split Duty VAT Indicator. The presence indicates the payer specified for Transportation Charges will pay transportation charges and any duties that apply to the shipment. The payer specified for Duties and Taxes will pay the VAT (Value-Added Tax) only.  This is an empty tag, any value inside is ignored. The payment method for Transportation charges must be UPS account. The UPS account must be a daily pickup account or an occasional account.
	SplitDutyVATIndicator *string `json:"SplitDutyVATIndicator,omitempty"`
}

// ShipmentPromotionalDiscountInformation PromotionalDiscountInformation container. This container contains discount information that the customer wants to request each time while placing a shipment.
type ShipmentPromotionalDiscountInformation struct {
	// PromoAliasCode Promotion Alias code  Required if PromotionalDiscountInformation container is present.
	PromoAliasCode string `json:"PromoAliasCode"`

	// PromoCode Promotion Code. A discount that is applied to the user.  Required if PromotionalDiscountInformation container is present.
	PromoCode string `json:"PromoCode"`
}

// ShipmentReferenceNumber Reference Number information container. Required for Trade Direct shipments.
type ShipmentReferenceNumber struct {
	// BarCodeIndicator If the indicator is present then the reference number's value will be bar coded on the label.  This is an empty tag, any value inside is ignored. Only one shipment-level or package-level reference number can be bar coded per shipment. In order to barcode a reference number, its value must be no longer than 14 alphanumeric characters or 24 numeric characters and cannot contain spaces.
	BarCodeIndicator *string `json:"BarCodeIndicator,omitempty"`

	// Code Shipment Reference number type code. The code specifies the Reference name. Refer to the Reference Number Code table.  Valid if the origin/destination pair is not US/US or PR/PR and character should be alpha-numeric.
	Code *string `json:"Code,omitempty"`

	// Value Customer supplied reference number.  Valid if the origin/destination pair is not US/US or PR/PR
	Value string `json:"Value"`
}

// ShipmentReturnService Type of Return service. When this container exists, the shipment is a return shipment.
type ShipmentReturnService struct {
	// Code Return Service types:
	// - 2 = UPS Print and Mail (PNM)
	// - 3 = UPS Return Service 1-Attempt (RS1)
	// - 5 = UPS Return Service 3-Attempt (RS3)
	// - 8 = UPS Electronic Return Label (ERL)
	// - 9 = UPS Print Return Label (PRL)
	// - 10 = UPS Exchange Print Return Label
	// - 11 = UPS Pack & Collect Service 1-Attempt Box 1
	// - 12 = UPS Pack & Collect Service 1-Attempt Box 2
	// - 13 = UPS Pack & Collect Service 1-Attempt Box 3
	// - 14 = UPS Pack & Collect Service 1-Attempt Box 4
	// - 15 = UPS Pack & Collect Service 1-Attempt Box 5
	// - 16 = UPS Pack & Collect Service 3-Attempt Box 1
	// - 17 = UPS Pack & Collect Service 3-Attempt Box 2
	// - 18 = UPS Pack & Collect Service 3-Attempt Box 3
	// - 19 = UPS Pack & Collect Service 3-Attempt Box 4
	// - 20 = UPS Pack & Collect Service 3-Attempt Box 5
	Code string `json:"Code"`

	// Description Return Service description.
	Description *string `json:"Description,omitempty"`
}

