// ShipmentShipFrom Ship From Container.  Required for return shipment.
//
// Required if pickup location is different from the shipper's address.
//
// Required for Trade Direct shipment.
type ShipmentShipFrom struct {
	// Address Ship from Address Container.  The package will be originating from or being shipped from this address. The shipment will be rated from this origin address to the destination ship to address.
	Address ShipFromAddress `json:"Address"`

	// AttentionName The ship from Attention name.
	// 35 characters are accepted, but for return Shipment only 30 characters will be printed on the label.  Required if ShipFrom tag is in the XML and Invoice or CO International forms is requested. If not present, will default to the Shipper Attention Name.
	AttentionName *string `json:"AttentionName,omitempty"`

	// CompanyDisplayableName Not applicable for ShipFrom.
	CompanyDisplayableName *string `json:"CompanyDisplayableName,omitempty"`

	// FaxNumber The Ship from fax number.  If Ship from country or territory is US 10 digits allowed, otherwise 1-15 digits allowed.
	FaxNumber *string `json:"FaxNumber,omitempty"`

	// Name The ship from location's name or company name.
	// 35 characters are accepted, but for return Shipment only 30 characters will be printed on the label.  Required if ShipFrom tag is in the XML.
	Name string `json:"Name"`

	// Phone Container for Phone Number.  If ShipFrom country or territory is US, PR, CA, and VI, the layout is:
	// area code, 7 digit phone number or
	// area code, 7 digit phone number, 4 digit extension number.
	//
	// For other countries or territories, the layout is:
	// country or territory code, area code, 7 digit number.
	//
	//  If ShipFrom tag is in the XML and International forms is requested.
	Phone *ShipFromPhone `json:"Phone,omitempty"`

	// TaxIDType Tax Identification Container.  Applies to EEI form only.
	TaxIDType *ShipFromTaxIDType `json:"TaxIDType,omitempty"`

	// TaxIdentificationNumber Company's Tax Identification Number at the pick up location.  Conditionally required if EEI form (International forms) is requested.
	// Applies to EEI Form only. This element has been deprecated, replacement can be found in the GlobalTaxInformation container.
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	TaxIdentificationNumber *string `json:"TaxIdentificationNumber,omitempty"`

	// VendorInfo Vendor Information Container
	VendorInfo *ShipFromVendorInfo `json:"VendorInfo,omitempty"`
}

// ShipmentShipTo Ship To Container.
type ShipmentShipTo struct {
	// Address Address Container.
	Address ShipToAddress `json:"Address"`

	// AttentionName Contact name at the consignee's location.  Required for: UPS Next Day Air® Early service, and when ShipTo country or territory is different than ShipFrom country or territory.
	//
	// Required if Invoice International form is requested.
	AttentionName *string `json:"AttentionName,omitempty"`

	// CompanyDisplayableName Not applicable for ShipTo
	CompanyDisplayableName *string `json:"CompanyDisplayableName,omitempty"`

	// EMailAddress Consignee's email address.
	EMailAddress *string `json:"EMailAddress,omitempty"`

	// FaxNumber Consignee's fax number.  If ShipTo country or territory is US 10 digits allowed, otherwise 1-15 digits allowed.
	FaxNumber *string `json:"FaxNumber,omitempty"`

	// LocationID Location ID is a unique identifier referring to a specific shipping/receiving location.  Location ID must be alphanumeric characters. All letters must be capitalized.
	LocationID *string `json:"LocationID,omitempty"`

	// Name Consignee's company name.  All other accounts must be either a daily pickup account or an occasional account.
	Name string `json:"Name"`

	// Phone Container for Phone Number
	Phone *ShipToPhone `json:"Phone,omitempty"`

	// TaxIdentificationNumber Consignee's tax identification number. This element has been deprecated, replacement can be found in the GlobalTaxInformation container.
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	TaxIdentificationNumber *string `json:"TaxIdentificationNumber,omitempty"`
}

// ShipmentShipmentIndicationType Container for Shipment Indication Type.  Required to indicate whether shipment is "Hold For Pickup At UPS Access Point" for use by approved shippers to identify a UPS Access Point location as an alternate delivery option during shipment preparation or "UPS Access Point™ Delivery", ship parcels directly to a UPS Access Point location for collection by the receiver.
type ShipmentShipmentIndicationType struct {
	// Code Valid values:
	// - '01' - Hold for Pickup at UPS Access Point aka Direct to Retail (D2R)
	// - '02' - UPS Access Point™ Delivery aka Retail to Retail (R2R)  If '01' code is present indicates shipment will be send to Retail location where it is held to consignee to claim.
	Code string `json:"Code"`

	// Description Description for the code.
	Description *string `json:"Description,omitempty"`
}

// ShipmentShipmentRatingOptions ShipmentRatingOptions container.
type ShipmentShipmentRatingOptions struct {
	// FRSShipmentIndicator Ground Freight Pricing Rates option indicator. If the Ground Freight Pricing Shipment indicator is enabled and Shipper number is authorized then Ground Freight Pricing rates should be returned in the response.  The Shipper account number must be qualified to receive Ground Freight Pricing Density Based Shipment rates. Only the Shipper account number taken from /ShipmentRequest/Shipment/FRSPaymentInformation/AccountNumber is used when checking qualification for Ground Freight Pricing Density Based rates.
	FRSShipmentIndicator *string `json:"FRSShipmentIndicator,omitempty"`

	// NegotiatedRatesIndicator Negotiated Rates option indicator. If the indicator is present and the Shipper is authorized then Negotiated Rates should be returned in the response.  Negotiated Rates are of two types Account Based Rates (ABR) and Web Discount Rates. Negotiated Rates are only returned for qualified Shipper Account Numbers.
	//
	// Eligibility is determined using the combination of UserId and the Shipper's Shipper Account Number. If the user is qualified, both Published rates and Negotiated rates are returned to the user. If the UserId and Shipper Account
	//
	// Number are not qualified for Negotiated rates, a warning message is returned that indicates ineligibility and only the Published rates are returned in the response. As per discount eligibility of user, negotiated rates in the response may contain ABR or Web discount rates.
	NegotiatedRatesIndicator *string `json:"NegotiatedRatesIndicator,omitempty"`

	// RateChartIndicator RateChartIndicator, if present in request, response will contain RateChart element.
	RateChartIndicator *string `json:"RateChartIndicator,omitempty"`

	// TPFCNegotiatedRatesIndicator This indicator applies for a third party (3P) / Freight collect (FC) shipment only.
	//
	// For 3P/FC shipment if the shipper wishes to request for the negotiated rates of the third party then this indicator should be included in the request.
	//
	// If authorized the 3P/FC negotiated rates will be applied to the shipment and rates will be returned in response.
	TPFCNegotiatedRatesIndicator *string `json:"TPFCNegotiatedRatesIndicator,omitempty"`

	// UserLevelDiscountIndicator If this indicator is present user level discount will be applied to rates if applicable  Conditions checked:
	// This indicator should be present
	// Shipper number should not be present
	// User should be eligible for user level discount
	UserLevelDiscountIndicator *string `json:"UserLevelDiscountIndicator,omitempty"`
}

// ShipmentShipmentServiceOptions Container for Shipment Service Options.
type ShipmentShipmentServiceOptions struct {
	// AccessPointCOD Access Point COD indicates COD is requested for a shipment.  Valid only for "01 - Hold For Pickup At UPS Access Point" Shipment Indication type. Shipment Access Point COD is valid only for countries or territories within E.U.
	// Not valid with (Shipment) COD.
	// Not available to shipment with return service.
	AccessPointCOD *ShipmentServiceOptionsAccessPointCOD `json:"AccessPointCOD,omitempty"`

	// COD COD container  Indicates COD is requested. Shipment COD is only available for EU origin countries or territories and for shippers account type Daily Pickup and Drop Shipping. Not available to shipment with return service.
	COD *ShipmentServiceOptionsCOD `json:"COD,omitempty"`

	// CommercialInvoiceRemovalIndicator CommercialInvoiceRemovalIndicator allows a shipper to dictate UPS to remove the Commercial Invoice from the user's shipment before the shipment is delivered to the ultimate consignee.
	CommercialInvoiceRemovalIndicator *string `json:"CommercialInvoiceRemovalIndicator,omitempty"`

	// DeliverToAddresseeOnlyIndicator Presence/Absence Indicator. Any value inside is ignored. DeliverToAddresseeOnlyIndicator is shipper specified restriction that requires the addressee to be the one who takes final delivery of the "Hold For PickUp at UPS Access Point" package. Presence of indicator means shipper restriction will apply to the shipment.  Only valid for Shipment Indication type "01 - Hold For PickUp at UPS Access Point".
	DeliverToAddresseeOnlyIndicator *string `json:"DeliverToAddresseeOnlyIndicator,omitempty"`

	// DeliveryConfirmation Delivery Confirmation container.   Valid for forward shipments only.
	//
	// Refer to Delivery Confirmation Origin-Destination Pairs in the Appendix for a list of valid values.
	DeliveryConfirmation *ShipmentServiceOptionsDeliveryConfirmation `json:"DeliveryConfirmation,omitempty"`

	// DirectDeliveryOnlyIndicator Presence/Absence Indicator. Any value inside is ignored. Direct Delivery Only (DDO) accessorial in a request would ensure that delivery is made only to the ship to address on the shipping label. This accessorial is not valid with Shipment Indication Type "01 - Hold For Pickup At UPS Access Point" and "02 - UPS Access Point™ Delivery".
	DirectDeliveryOnlyIndicator *string `json:"DirectDeliveryOnlyIndicator,omitempty"`

	// DropoffAtUPSFacilityIndicator Drop off At UPS Facility indicator. The empty tag means indicator is present.  This accessorial is only valid for UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday Shipment.
	DropoffAtUPSFacilityIndicator *string `json:"DropoffAtUPSFacilityIndicator,omitempty"`

	// EPRAReleaseCode Package Release code allows the consignee or claimant to pick-up a package at a UPS Access Point™. The shipper must provide the Package Release Code to the consignee so that they can provide the code to the UPS Access Point personnel as another item for authentication before the package is released to them. Package Release Code is only valid with ShipmentIndicationType 01 - Hold for Pickup at UPS Access Point™.  The release code must be between length 4 and 6 and only contain numbers.
	EPRAReleaseCode *string `json:"EPRAReleaseCode,omitempty"`

	// ExchangeForwardIndicator Exchange forward indicator presence at shipment level is required to create exchange forward Shipments.  In the label routing Instruction text will be defaulted to "EXCHANGE-LIKE ITEM ONLY".
	ExchangeForwardIndicator *string `json:"ExchangeForwardIndicator,omitempty"`

	// HoldForPickupIndicator Hold For Pickup indicator. The empty tag means indicator is present.  This accessorial is only valid for UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday Shipment.
	HoldForPickupIndicator *string `json:"HoldForPickupIndicator,omitempty"`

	// ImportControlIndicator Indicates that the Shipment is an ImportControl shipment.
	ImportControlIndicator *string `json:"ImportControlIndicator,omitempty"`

	// InsideDelivery Inside delivery accessory. Valid values:
	// 01 - White Glove,
	// 02 - Room of Choice,
	// 03 - Installation,
	// 04 - Over Threshold Fee.
	// Default is Room of Choice.  Shippers account needs to have a valid contract for Heavy Goods Service.
	InsideDelivery *string `json:"InsideDelivery,omitempty"`

	// InternationalForms International Forms information. This is applicable to Trade Direct SMALLPACKAGE International Child movements and not applicable to Trade Direct Master or Trade Direct LTL Child movements.
	InternationalForms *ShipmentServiceOptionsInternationalForms `json:"InternationalForms,omitempty"`

	// ItemDisposal Presence/Absence indicator. True if present; false otherwise. Any value is ignored. If present, indicates that the customer would like items disposed.  Shippers account needs to have a valid contract for Heavy Goods Service.
	ItemDisposal *string `json:"ItemDisposal,omitempty"`

	// LabelDelivery Container for the Label Delivery accessorial. Note - LabelDelivery is not applicable for GFP and Mail Innovations Forward shipment.  Required for shipments with either Electronic Return Label Return Service or ImportControl Electronic LabelMethod type. Optional for shipments with Print Return Label Return Service or ImportControl Print LabelMethod type or Forward movement.  If this container is present for shipments with either Electronic Return Label Return Service or ImportControl Electronic LabelMethod type, either of the LabelLinksIndicator or EMail container should be provided. For shipments with Print Return Label Return Service or ImportControl Print LabelMethod type or Forward movement, only LabelLinksIndicator is valid option for LabelDelivery container.
	LabelDelivery *ShipmentServiceOptionsLabelDelivery `json:"LabelDelivery,omitempty"`

	// LabelMethod Type of ImportControl Label. This container is applicable only for ImportControl shipments.  This container is applicable only for ImportControl shipments.
	LabelMethod *ShipmentServiceOptionsLabelMethod `json:"LabelMethod,omitempty"`

	// LiftGateForDeliveryIndicator Lift Gate For Delivery indicator. The empty tag means indicator is present.  Lift Gate for Delivery is not allowed with Hold For Pickup for a UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday shipment.
	//
	// When both Hold for Pickup and Drop Off At UPS Facility are selected, neither of the Lift Gate accessorial (Pick Up or Delivery) are allowed for a UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday shipment.
	//
	// This accessorial is only valid for UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday Shipment.
	LiftGateForDeliveryIndicator *string `json:"LiftGateForDeliveryIndicator,omitempty"`

	// LiftGateForPickUpIndicator Lift Gate For Pick Up indicator. The empty tag means indicator is present.  Lift Gate for Pickup is not allowed with Drop Off At UPS Facility for a UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday shipment.
	//
	// When both Hold for Pickup and Drop Off At Facility are selected, neither of the Lift Gate accessorial (Pick Up or Delivery) are allowed for a UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday shipment.
	//
	// This accessorial is only valid for UPS Worldwide Express Freight and UPS Worldwide Express Freight Midday Shipment.
	LiftGateForPickUpIndicator *string                                       `json:"LiftGateForPickUpIndicator,omitempty"`
	Notification               *[]ShipmentServiceOptionsNotification         `json:"Notification,omitempty"`
	PreAlertNotification       *[]ShipmentServiceOptionsPreAlertNotification `json:"PreAlertNotification,omitempty"`

	// RestrictedArticles Restricted Articles container.
	RestrictedArticles *ShipmentServiceOptionsRestrictedArticles `json:"RestrictedArticles,omitempty"`

	// ReturnOfDocumentIndicator The flag indicates the ReturnOfDocument accessorial has been requested.  Valid for Poland to Poland forward shipment only.
	ReturnOfDocumentIndicator *string `json:"ReturnOfDocumentIndicator,omitempty"`

	// SDLShipmentIndicator The presence of the tag SDLShipmentIndicator indicates Shipment is SDL. SDLShipmentIndicator presence means EEI form/ EEI Filing option required.
	SDLShipmentIndicator *string `json:"SDLShipmentIndicator,omitempty"`

	// SaturdayDeliveryIndicator Saturday delivery indicator. The presence indicates Saturday delivery is requested and the absence indicates Saturday delivery is not requested.  This is an empty tag, any value inside is ignored.
	SaturdayDeliveryIndicator *string `json:"SaturdayDeliveryIndicator,omitempty"`

	// SaturdayPickupIndicator Saturday pickup indicator. The presence indicates Saturday pickup is requested and the absence indicates Saturday pickup is not requested.  This is an empty tag, any value inside is ignored.
	SaturdayPickupIndicator *string `json:"SaturdayPickupIndicator,omitempty"`

	// UPScarbonneutralIndicator UPS carbon offsets indicator presence at shipment level is required to create carbon offsets Shipments.
	UPScarbonneutralIndicator *string `json:"UPScarbonneutralIndicator,omitempty"`

	// VerifiedDelivery Protected Delivery container required for Secure Pin Delivery. Protected Delivery will offer shippers extra security to ensure their packages are delivered to the intended recipient.
	VerifiedDelivery *ShipmentServiceOptionsVerifiedDelivery `json:"VerifiedDelivery,omitempty"`
}

// ShipmentShipper Container for the Shipper's information.
type ShipmentShipper struct {
	// Address Address tag Container.  The package should be returned to this address if the package is undeliverable.
	//
	// This address appears on the upper left hand corner of the label.
	//
	// Note: If the ShipFrom container is not present then this address will be used as the ShipFrom address. If this address is used as the ShipFrom the shipment will be rated from this origin address.
	Address ShipperAddress `json:"Address"`

	// AttentionName Shippers Attention Name.
	//
	// For forward Shipment 35 characters are accepted, but only 30 characters will be printed on the label.  Required if destination is international. Required if Invoice and CO International forms are requested and the ShipFrom address is not present.
	AttentionName *string `json:"AttentionName,omitempty"`

	// CompanyDisplayableName Shipper's CompanyDisplayableName.
	//
	// The CompanyDisplayableName will be displayed in tracking results and notification messages in place of the name associated with the shipper account.
	// The original shipper account name will be displayed for all Return Services and Import Control Shipments.  This is available for Shipper accounts enabled by UPS and applies to Forward Shipments.
	CompanyDisplayableName *string `json:"CompanyDisplayableName,omitempty"`

	// EMailAddress Shipper's email address.
	EMailAddress *string `json:"EMailAddress,omitempty"`

	// FaxNumber Shipper's Fax Number.
	FaxNumber *string `json:"FaxNumber,omitempty"`

	// Name Shippers company name.
	//
	// For forward Shipment 35 characters are accepted, but only 30 characters will be printed on the label.
	Name string `json:"Name"`

	// Phone Container tag for Phone Number.
	Phone *ShipperPhone `json:"Phone,omitempty"`

	// ShipperNumber Shipper's six digit alphanumeric account number.
	//
	// Must be associated with the UserId specified in the AccessRequest XML.
	//
	// The account must be a valid UPS account number that is active.
	//
	// For US, PR and CA accounts, the account must be either a daily pickup account, an occasional account, or a customer B.I.N account.
	//
	// Drop Shipper accounts are valid for return service shipments only if the account is Trade Direct (TD) enabled.
	//
	// All other accounts must be either a daily pickup account or an occasional account.
	ShipperNumber string `json:"ShipperNumber"`

	// TaxIdentificationNumber Shipper's Tax Identification Number.  Conditionally required if EEI form (International forms) is requested and ship From is not mentioned. This element has been deprecated, replacement can be found in the GlobalTaxInformation container.
	// Deprecated: this property has been marked as deprecated upstream, but no `x-deprecated-reason` was set
	TaxIdentificationNumber *string `json:"TaxIdentificationNumber,omitempty"`
}

// ShipmentTradeDirect A UPS product that enables customers to ship directly from a manufacturer to end consumers in a different country.
type ShipmentTradeDirect struct {
	// Child A small package or LTL/TL shipment associated with a Trade Direct Master.
	Child *TradeDirectChild `json:"Child,omitempty"`

	// CurrencyCode The currency code for the shipment as per ISO 4217.
	CurrencyCode string `json:"CurrencyCode"`

	// GeneralDescriptionOfGoods General description of the goods being shipped. It is required for master shipment.
	GeneralDescriptionOfGoods *string `json:"GeneralDescriptionOfGoods,omitempty"`

	// Master A collection of small package and LTL/TL shipments that are transported by UPS from the customer to the destination CFS.
	Master *TradeDirectMaster `json:"Master,omitempty"`

	// ShipmentType Consolidated shipment types.
	//
	// Valid values:
	// - TRADEDIRECTAIR =  TradeDirect Air - consolidation, custom clearance, deconsolidation and delivery to multiple addresses
	//                     within destination country, with Airport-to-door or door-to-door.
	//
	// - TRADEDIRECTOCEAN = TradeDirect Ocean - consolidation, ocean transportation, customs clearance, deconsolidation and delivery
	//                      to multiple addresses within a destination country, with port-to-door and door-to-door service from shipper to consignee. Available from more than 70 ports.
	//
	// - TRADEDIRECTCROSSBORDER = TradeDirect CrossBoarder - consolidation, customs clearance, deconsolidation and delivery to multiple addresses
	//                            within the destination country, with door-to-door service across North American borders.
	ShipmentType ShipmentTradeDirectShipmentType `json:"ShipmentType"`
}

// ShipmentTradeDirectShipmentType Consolidated shipment types.
//
// Valid values:
//
//   - TRADEDIRECTAIR =  TradeDirect Air - consolidation, custom clearance, deconsolidation and delivery to multiple addresses
//     within destination country, with Airport-to-door or door-to-door.
//
//   - TRADEDIRECTOCEAN = TradeDirect Ocean - consolidation, ocean transportation, customs clearance, deconsolidation and delivery
//     to multiple addresses within a destination country, with port-to-door and door-to-door service from shipper to consignee. Available from more than 70 ports.
//
//   - TRADEDIRECTCROSSBORDER = TradeDirect CrossBoarder - consolidation, customs clearance, deconsolidation and delivery to multiple addresses
//     within the destination country, with door-to-door service across North American borders.
type ShipmentTradeDirectShipmentType string

// ShipmentWorldEase WorldEase is a contract service offering in the UPS shipping that decreases brokerage fees by consolidating
